import{_ as a,o as s,c as n,ag as t}from"./chunks/framework.DlQ8ZhpE.js";const h=JSON.parse('{"title":"Features","description":"","frontmatter":{"title":"Features","order":2},"headers":[],"relativePath":"docs/features/index.md","filePath":"en/docs/features/index.md"}'),o={name:"docs/features/index.md"};function i(r,e,p,l,d,c){return s(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h1><p>The stages a request passes through in Pavonis:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>client</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>select site by host / path_prefix ── no match ──► 404</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>client auth (if enabled) ─────────── failed ────► 401</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>request rate limit ───────────────── exceeded ──► 429</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>header modification → outbound connection (IP pool / request proxy) ──► upstream</span></span>
<span class="line"><span>(uploads and downloads are subject to traffic limits)</span></span></code></pre></div><h2 id="site-modes" tabindex="-1">Site Modes <a class="header-anchor" href="#site-modes" aria-label="Permalink to &quot;Site Modes&quot;">​</a></h2><p>The core capability of Pavonis is expressed through <strong>site modes</strong>. A single instance can run any number of sites simultaneously, each choosing a mode that covers container images, code hosting, ML platforms, package management and more.</p><p>→ <a href="./../sites/">Site Modes Documentation</a></p><h2 id="outbound-ip-pool" tabindex="-1">Outbound IP Pool <a class="header-anchor" href="#outbound-ip-pool" aria-label="Permalink to &quot;Outbound IP Pool&quot;">​</a></h2><p>When your server holds a large IPv6 address block (e.g. a <code>/48</code> subnet from HE Tunnel Broker), you can enable the IP pool to let Pavonis select outbound IPs from the pool at random or by rule, effectively bypassing per-IP rate limits imposed by upstream platforms. Supports <code>random</code> and <code>ip_hash</code> (pinned by client IP) strategies, with per-site override support.</p><p>→ <a href="./ip-pool">IP Pool Documentation</a></p><h2 id="traffic-and-request-rate-limiting" tabindex="-1">Traffic and Request Rate Limiting <a class="header-anchor" href="#traffic-and-request-rate-limiting" aria-label="Permalink to &quot;Traffic and Request Rate Limiting&quot;">​</a></h2><p>Limit bandwidth and per-second, per-minute and per-hour request counts per client, and optionally cap the combined bandwidth of all clients, to keep the proxy from consuming excessive resources or being abused.</p><p>→ <a href="./rate-limiting">Rate Limiting Documentation</a></p><h2 id="authentication-headers-and-request-proxy" tabindex="-1">Authentication, Headers and Request Proxy <a class="header-anchor" href="#authentication-headers-and-request-proxy" aria-label="Permalink to &quot;Authentication, Headers and Request Proxy&quot;">​</a></h2><p>Container registry and <code>any_url</code> sites support client authentication, with hot-reloadable user files (no restart required to update the user list). Automatically strips reverse-proxy-related headers to prevent leaking proxy chain information to upstreams. Upstream requests can go through one or more request proxies, with automatic switching when one is unreachable.</p><p>→ <a href="./auth-and-headers">Auth, Headers and Request Proxy Documentation</a></p>`,15)])])}const m=a(o,[["render",i]]);export{h as __pageData,m as default};
